    def _mask_event_type(self, logits: torch.FloatTensor) -> torch.FloatTensor:
        """At event_type position, allow all valid event type first tokens."""
        if not self._event_type_first_token:
            return logits
        return self._apply_first_token_mask(
            logits, self._event_type_first_token, set(self.spec.event_types)
